// Ubah nilai pada SETTINGS, lalu Deploy Full.
const SETTINGS = {
    id_group: 'kelompok-00',
    node_id: 'node-00',
    admin_username: 'admin',
    admin_password: 'admin123'
};

const validId = /^[A-Za-z0-9_-]{1,40}$/;
if (!validId.test(SETTINGS.id_group) || !validId.test(SETTINGS.node_id) ||
    !SETTINGS.admin_username || !SETTINGS.admin_password) {
    global.set('faceConfig', null);
    node.status({fill:'red',shape:'ring',text:'konfigurasi tidak valid'});
    node.error('Periksa id_group, node_id, username, dan password admin.');
    return [[{action:'unsubscribe',topic:true}], null, null];
}

const base = SETTINGS.id_group + '/' + SETTINGS.node_id;
const topics = {
    face_status: base + '/face/status',
    face_register: base + '/face/register',
    face_profiles: base + '/face/profiles',
    esp_status: base + '/esp32/status',
    camera_status: base + '/camera/status'
};
const subscriptions = [
    topics.face_status,
    topics.face_register,
    topics.esp_status,
    topics.camera_status
];
const fingerprint = JSON.stringify(SETTINGS);
const changed = context.get('fingerprint') !== fingerprint ||
                !global.get('faceConfig') || msg.kind === 'configure';

if (changed) {
    global.set('faceConfig', {...SETTINGS, topics});
    context.set('fingerprint', fingerprint);
    flow.set('adminSessions', {});
    flow.set('adminAttempts', {});
    flow.set('pendingFace', {});
    flow.set('lastFaceEvent', {state:'idle', face_ids:[]});
}

const statusText = String(msg.status?.text || '').toLowerCase();
const connected = statusText.includes('connected') &&
                  !statusText.includes('disconnected');
const reconnected = connected && context.get('brokerConnected') !== true;
if (msg.status) context.set('brokerConnected', connected);

let mqttMessages = null;
if (changed || reconnected) {
    mqttMessages = [
        {action:'unsubscribe', topic:true},
        {action:'subscribe', topic:subscriptions.map(topic => ({topic,qos:1}))}
    ];
}

const init = changed ? {
    op:'init',
    payload:[],
    topic:`CREATE TABLE IF NOT EXISTS users (
      face_id TEXT PRIMARY KEY,
      nama TEXT NOT NULL,
      nim TEXT NOT NULL,
      kelas TEXT NOT NULL,
      foto_base64 TEXT DEFAULT '',
      status TEXT NOT NULL DEFAULT 'idle',
      updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
    )`
} : null;
const refresh = changed ? {kind:'refresh'} : null;
node.status({fill:'green',shape:'dot',text:SETTINGS.id_group+' / '+SETTINGS.node_id});
return [mqttMessages, init, refresh];

const p=msg.payload||{};
flow.set('lastFaceAt',Date.now());
flow.set('lastCameraAt',Date.now());
flow.set('lastFaceEvent',{
    state:p.state||'idle',
    face_id:p.face_id||'',
    face_ids:Array.isArray(p.face_ids)?p.face_ids:[],
    confidence:Number(p.confidence)||0,
    reason:p.reason||null,
    timestamp:p.timestamp||new Date().toISOString()
});
if(!Array.isArray(p.users)||!p.users.length){
    msg.op='refresh';
    msg.topic='SELECT * FROM users ORDER BY nama COLLATE NOCASE';
    msg.payload=[];
    return msg;
}
const cases=[],holders=[],caseValues=[],faceIds=[];
p.users.forEach((u)=>{
    if(!u||!u.face_id||!['idle','available','unavailable'].includes(u.status))return;
    const faceId=String(u.face_id).trim();
    if(!faceId)return;
    cases.push('WHEN ? THEN ?');
    holders.push('?');
    caseValues.push(faceId,u.status);
    faceIds.push(faceId);
});
if(!holders.length)return null;
msg.op='status_update';
msg.topic=`UPDATE users SET status=CASE face_id ${cases.join(' ')} ELSE status END, updated_at=CURRENT_TIMESTAMP WHERE face_id IN (${holders.join(',')})`;
msg.payload=[...caseValues,...faceIds];
delete msg.params;
return msg;

const p=msg.kind?msg:(msg.payload||{});
const c=global.get('faceConfig');
const now=Date.now();
const SESSION_MS=8*60*60*1000;
let sessions=flow.get('adminSessions')||{};
for(const token of Object.keys(sessions))if(sessions[token].expires_ms<=now)delete sessions[token];
flow.set('adminSessions',sessions);

function response(value){
    return [null,{payload:value}];
}
function clientOK(value){
    return typeof value==='string'&&/^[A-Za-z0-9_-]{8,100}$/.test(value);
}
function tokenOK(value){
    const s=sessions[value];
    return !!s&&s.expires_ms>now&&s.client_id===p.client_id;
}
function token(){
    return Array.from({length:4},()=>Math.random().toString(36).slice(2)).join('')+
           now.toString(36);
}

if(p.kind==='login'){
    if(!c||!clientOK(p.client_id))return response({kind:'auth',status:'ERROR',client_id:p.client_id||'',message:'Konfigurasi belum siap'});
    let attempts=flow.get('adminAttempts')||{};
    const a=attempts[p.client_id]||{count:0,blocked_until:0};
    if(a.blocked_until>now)return response({kind:'auth',status:'ERROR',client_id:p.client_id,message:'Terlalu banyak percobaan. Tunggu satu menit.'});
    if(String(p.username)!==c.admin_username||String(p.password)!==c.admin_password){
        a.count++;
        if(a.count>=5){a.count=0;a.blocked_until=now+60000;}
        attempts[p.client_id]=a;flow.set('adminAttempts',attempts);
        return response({kind:'auth',status:'ERROR',client_id:p.client_id,message:'Username atau password salah'});
    }
    delete attempts[p.client_id];flow.set('adminAttempts',attempts);
    const t=token();
    sessions[t]={client_id:p.client_id,expires_ms:now+SESSION_MS};
    flow.set('adminSessions',sessions);
    return response({kind:'auth',status:'OK',client_id:p.client_id,session_token:t,expires_ms:now+SESSION_MS});
}
if(p.kind==='session'){
    const ok=clientOK(p.client_id)&&tokenOK(p.session_token);
    return response({kind:'auth',status:ok?'OK':'UNAUTHORIZED',client_id:p.client_id||'',session_token:ok?p.session_token:'',expires_ms:ok?sessions[p.session_token].expires_ms:0,message:ok?'':'Sesi berakhir. Silakan login kembali.'});
}
if(p.kind==='logout'){
    if(p.session_token)delete sessions[p.session_token];
    flow.set('adminSessions',sessions);
    return response({kind:'auth',status:'LOGGED_OUT',client_id:p.client_id||''});
}
if(p.kind==='refresh'){
    msg.op='refresh';msg.topic='SELECT * FROM users ORDER BY nama COLLATE NOCASE';msg.payload=[];
    delete msg.params;
    return[msg,null];
}
if(!['create','update','delete'].includes(p.kind))return null;
if(!clientOK(p.client_id)||!tokenOK(p.session_token)){
    return response({kind:'feedback',ok:false,unauthorized:true,client_id:p.client_id||'',message:'Sesi admin berakhir. Silakan login kembali.'});
}
if(p.kind==='delete'){
    const faceId=String(p.face_id||'').trim();
    if(!faceId)return response({kind:'feedback',ok:false,client_id:p.client_id,message:'face_id tidak valid'});
    msg.op='delete';msg.face_id=faceId;msg.client_id=p.client_id;
    msg.topic='DELETE FROM users WHERE face_id=?';msg.payload=[faceId];
    delete msg.params;
    return[msg,null];
}
const u=p.user||{};
const faceId=String(u.face_id||'').trim();
const nama=String(u.nama||'').trim();
const nim=String(u.nim||'').trim();
const kelas=String(u.kelas||'').trim();
const foto=String(u.foto_base64||'').slice(0,2100000);
if(!faceId||!nama||!nim||!kelas)return response({kind:'feedback',ok:false,client_id:p.client_id,message:'Face ID, nama, NIM, dan kelas wajib diisi'});
if(!/^FACE-[A-Z0-9_-]{1,20}$/.test(faceId))return response({kind:'feedback',ok:false,client_id:p.client_id,message:'Format face_id tidak valid'});
msg.op=p.kind;msg.face_id=faceId;msg.client_id=p.client_id;
if(p.kind==='create'){
    msg.topic="INSERT INTO users(face_id,nama,nim,kelas,foto_base64,status,updated_at) VALUES(?,?,?,?,?,'idle',CURRENT_TIMESTAMP)";
    msg.payload=[faceId,nama.slice(0,100),nim.slice(0,30),kelas.slice(0,30),foto];
}else{
    msg.topic='UPDATE users SET nama=?,nim=?,kelas=?,foto_base64=?,updated_at=CURRENT_TIMESTAMP WHERE face_id=?';
    msg.payload=[nama.slice(0,100),nim.slice(0,30),kelas.slice(0,30),foto,faceId];
}
delete msg.params;
return[msg,null];

const op=msg.op||'';
const c=global.get('faceConfig')||{id_group:'kelompok-00',node_id:'node-00',topics:{face_profiles:'kelompok-00/node-00/face/profiles'}};
const system=global.get('faceSystem')||{};
system.sqlite=true;system.nodered=true;
system.esp32=Date.now()-(flow.get('lastEsp32At')||0)<15000;
system.camera=Date.now()-(flow.get('lastCameraAt')||0)<70000;
global.set('faceSystem',system);
if(op==='init'||op==='status_update'||['create','update','delete'].includes(op)){
    if(op==='create'&&flow.get('pendingFace')?.face_id===msg.face_id)flow.set('pendingFace',{});
    const refresh={op:'refresh',topic:'SELECT * FROM users ORDER BY nama COLLATE NOCASE',payload:[]};
    const feedback=['create','update','delete'].includes(op)?{payload:{kind:'feedback',ok:true,client_id:msg.client_id||'',message:op==='delete'?'Pengguna berhasil dihapus':'Data pengguna berhasil disimpan'}}:null;
    return[refresh,null,null,feedback];
}
if(op!=='refresh')return null;
const users=Array.isArray(msg.payload)?msg.payload:[];
const state={kind:'state',users,pending:flow.get('pendingFace')||{},system,config:c,last_face:flow.get('lastFaceEvent')||{state:'idle',face_ids:[]},updated_at:new Date().toISOString()};
const profiles={};users.forEach(u=>profiles[u.face_id]=u.nama);
const encoded=JSON.stringify(profiles);
let profileMsg=null;
if(flow.get('profilesHash')!==encoded){
    flow.set('profilesHash',encoded);
    profileMsg={topic:c.topics?.face_profiles||c.id_group+'/'+c.node_id+'/face/profiles',payload:JSON.stringify({profiles,updated_at:new Date().toISOString()}),qos:1,retain:true};
}
return[null,{payload:state},profileMsg,null];

const s=global.get('faceSystem')||{};s.sqlite=false;global.set('faceSystem',s);
const text=String(msg.error?.message||'');
const message=text.includes('UNIQUE')?'face_id sudah terdaftar':text.includes('locked')?'SQLite sedang terkunci; coba kembali':'Operasi database gagal: '+text;
msg.payload={kind:'feedback',ok:false,client_id:msg.client_id||'',message};return msg;

let sql=String(msg.topic||'');

function fail(message){
    return [null,{payload:{kind:'feedback',ok:false,client_id:msg.client_id||'',message}}];
}

// Format lama: ambil nilai msg.params sesuai urutan placeholder $nama.
if(msg.params&&typeof msg.params==='object'&&!Array.isArray(msg.params)){
    const keys=sql.match(/\$[A-Za-z_][A-Za-z0-9_]*/g)||[];
    const missing=keys.filter(key=>!Object.prototype.hasOwnProperty.call(msg.params,key));
    if(missing.length)return fail('Parameter SQLite tidak tersedia: '+[...new Set(missing)].join(', '));
    msg.payload=keys.map(key=>msg.params[key]);
    delete msg.params;
}

if(!Array.isArray(msg.payload))msg.payload=[];

// node-red-node-sqlite 2.0.1 menghitung placeholder dari karakter '$'.
// Konversi setiap '?' menjadi placeholder bernama unik agar binding tidak dibuang.
let parameterIndex=0;
if(sql.includes('?')){
    sql=sql.replace(/\?/g,()=>'$p'+(++parameterIndex));
    msg.topic=sql;
}

const placeholders=sql.match(/\$[A-Za-z_][A-Za-z0-9_]*/g)||[];
if(placeholders.length!==msg.payload.length){
    return fail('Jumlah parameter SQLite tidak cocok: query '+placeholders.length+', data '+msg.payload.length);
}

if(msg.op==='create'){
    const [faceId,nama,nim,kelas]=msg.payload;
    if(!String(faceId||'').trim())return fail('Face ID kosong sebelum masuk SQLite');
    if(!String(nama||'').trim())return fail('Nama kosong sebelum masuk SQLite');
    if(!String(nim||'').trim())return fail('NIM kosong sebelum masuk SQLite');
    if(!String(kelas||'').trim())return fail('Kelas kosong sebelum masuk SQLite');
}

if(msg.op==='update'){
    const [nama,nim,kelas,,faceId]=msg.payload;
    if(!String(faceId||'').trim())return fail('Face ID edit kosong sebelum masuk SQLite');
    if(!String(nama||'').trim()||!String(nim||'').trim()||!String(kelas||'').trim()){
        return fail('Nama, NIM, dan kelas wajib diisi');
    }
}

return [msg,null];
